"""Build the active reception page from the current supplier catalog.
The historical catalog in reception_data.py is retained for saved quotations only.
"""
from pathlib import Path
from html import escape as e
import json,re
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'tools/cafefriends_catalog.json').read_text())
V=DATA['version'];IMG='/assets/img/reception/cafefriends/'
def photo(filename,alt,lazy=True):
 return f'<img src="{IMG+filename}" alt="{e(alt)}" width="960" height="640" '+('loading="lazy" decoding="async"' if lazy else 'fetchpriority="high"')+'>'
def head(eyebrow,title,desc=''):
 return f'<div class="section-head"><div class="eyebrow">{eyebrow}</div><h2 class="h-l">{title}</h2>'+ (f'<p class="lead">{desc}</p>' if desc else '')+'</div>'
def build_web():
 p=ROOT/'reception/index.html';html=p.read_text();title='메가스팟 출장 케이터링 | 테이블 세팅·박스·다과·도시락';desc='행사에 맞는 다섯 가지 제공 방식과 식사·샌드위치·핑거푸드·디저트·떡·한과·음료 메뉴. 희망 구성과 인원·메뉴를 골라 메가스팟에 상담하세요.'
 html=re.sub(r'<title>.*?</title>',f'<title>{title}</title>',html)
 html=re.sub(r'(<meta (?:name="description"|property="og:description"|name="twitter:description") content=")[^"]*',lambda m:m[1]+desc,html)
 html=re.sub(r'(<meta (?:property="og:title"|name="twitter:title") content=")[^"]*',lambda m:m[1]+title,html)
 html=html.replace('https://megaspot.kr/assets/img/reception/hero.jpg','https://megaspot.kr'+IMG+'field-80.jpg')
 schema={'@context':'https://schema.org','@type':'Service','name':'메가스팟 출장 케이터링','url':'https://megaspot.kr/reception/','description':desc,'image':'https://megaspot.kr'+IMG+'field-80.jpg','provider':{'@type':'Organization','name':'메가스팟','url':'https://megaspot.kr/'}}
 html=re.sub(r'<script type="application/ld\+json">.*?</script>','<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False)+'</script>',html,flags=re.S)
 main='''<main id="main" data-reception-provider="cafefriends">
<section class="page-hero cf-hero"><div class="container"><div class="crumbs"><a href="/">홈</a><span>/</span><span>출장 케이터링</span></div><div class="reception-hero mt-3"><div><div class="eyebrow">Megaspot Catering</div><h1 class="h-xl">모임에 맞는 메뉴,<br>공간에 어울리는 세팅</h1><p class="lead">회의의 다과부터 네트워킹 핑거푸드와 든든한 식사까지.<br>원하는 방식과 메뉴를 고르면 메가스팟이 함께 상담합니다.</p><div class="cf-facts"><span><b>5가지</b><small>제공 방식</small></span><span><b>30가지</b><small>참고 메뉴</small></span><span><b>맞춤</b><small>행사별 구성 상담</small></span></div><div class="row mt-3"><a class="btn btn-primary" href="#calc">우리 행사 구성하기 →</a><a class="btn btn-light" href="/assets/docs/megaspot-reception-guide.pdf?v=VERSION" target="_blank" rel="noopener">소개서 PDF ↗</a></div><p class="tiny muted mt-2">메뉴·출장·세팅비는 부가세 별도이며 최종 공급가액에 부가세 10%를 더합니다. 공간 대관료는 별도입니다.</p></div><figure>HERO<figcaption>카페프렌즈 제공 현장 사례 · 장식·기물·제공 범위는 행사별 상담</figcaption></figure></div><nav class="reception-jump" aria-label="케이터링 페이지 목차"><a href="#formats">제공 방식</a><a href="#packages">행사별 추천</a><a href="#calc">구성·견적 상담</a><a href="#catalog">메뉴 선택</a><a href="#gallery">현장 사례</a><a href="#faq">주문 안내</a></nav></div></section>
'''.replace('HERO',photo('field-80.jpg','꽃과 기물에 핑거푸드를 배치한 협력사 케이터링 테이블',False))
 main+='<section class="section sec-white sec-line" id="formats"><div class="container">'+head('Choose your style','어떤 방식으로 준비할까요?','현장 연출부터 개별 포장까지, 행사에 맞는 방식을 선택하세요.')+'<div class="cf-formats">'
 for i,f in enumerate(DATA['formats'],1):
  main+=f'<article class="cf-format"><figure>{photo(f["image"],f["caption"])}<figcaption>{e(f["caption"])}</figcaption></figure><div class="cf-format-body"><div class="eyebrow">0{i} / {e(f["tag"])}</div><h3>{e(f["name"])}</h3><p>{e(f["intro"])}</p><p class="tiny muted">{e(f["check"])}</p><a class="btn btn-light btn-sm" href="#calc" data-reception-format="{f["id"]}">이 방식 선택 →</a></div></article>'
 main+='</div></div></section><section class="section sec-line" id="packages"><div class="container">'+head('Made for your event','고르기 어려울 때, 이 메뉴를 참고하세요','테이블 세팅·박스 케이터링의 1인 가격대별 참고 메뉴입니다. 예산과 취향을 알려 주시면 메뉴를 함께 조정합니다.')+'<div class="cf-packages">'
 for co in [c for c in DATA['offerings'] if c['id']!='cf-custom']:
  main+=f'<article class="cf-package" id="course-{co["id"]}">{photo(co["image"],co["name"]+" 메뉴 참고 사진")}<div><p class="tiny muted">{e(co["tag"])}</p><h3>{e(co["name"])}</h3><p>{e(co["intro"])}</p><ul class="cf-course-menu">{''.join('<li>'+e(m)+'</li>' for m in co['menus'])}</ul><p class="cf-reference-note">1인 가격대별 참고 메뉴이며 고정 구성은 아닙니다. 계절과 요청에 따라 변경 가능합니다.</p><p class="cf-package-price" data-cf-price="{co["id"]}">1인 {co['price']:,}원 · 부가세 별도</p><a class="btn btn-light btn-sm" href="#calc" data-reception-course="{co["id"]}">이 가격대로 계산 →</a></div></article>'
 main+='</div></div></section><section class="section sec-white sec-line" id="calc"><div class="container">'+head('Plan your catering','우리 행사에 맞게 구성해 보세요','제공 방식·행사 인원·희망 메뉴를 남겨 주세요. 정해지지 않은 부분은 상담에서 함께 결정합니다.')
 fmt=''.join(f'<option value="{f["id"]}">{e(f["name"])}</option>' for f in DATA['formats'])
 courses=''.join(f'<option value="{co["id"]}"'+(' selected' if co['id']=='cf-classic' else '')+'>'+e(co['name'])+'</option>' for co in DATA['offerings'])
 main+=f'''<div id="reception-calc" class="cc-grid cf-calc"><form class="cc-form card" id="cf-form"><div class="cc-step"><label class="cc-step-h" for="reception-format"><span>1</span>제공 방식</label><select class="input" id="reception-format" name="reception_format"><option value="">상담 후 결정</option>{fmt}</select></div><div class="cc-step"><label class="cc-step-h" for="reception-course"><span>2</span><strong id="reception-choice-label">희망 구성 · 참고 코스</strong></label><select class="input" id="reception-course" name="reception_course">{courses}</select><p class="tiny muted mt-2" id="reception-choice-hint">테이블·박스는 참고 코스를, 다과·도시락은 1인 예산을 선택합니다.</p></div><div class="cc-step"><label class="cc-step-h" for="reception-people"><span>3</span>케이터링 인원</label><div class="cc-people"><input class="input" id="reception-people" name="reception_people" type="number" min="1" max="100000" step="1" inputmode="numeric" value="50"><span>명</span></div><div class="pick cc-quick">'''+''.join(f'<button type="button" data-reception-people="{n}" aria-pressed="'+str(n==50).lower()+f'">{n}명</button>' for n in [30,50,80,100,150,200])+'''</div></div><div class="cc-step" id="reception-budget-group"><label class="cc-step-h" for="reception-budget"><span>4</span>희망 1인 예산 <small>선택</small></label><input class="input" id="reception-budget" name="reception_budget" type="number" min="1" max="10000000" step="1" inputmode="numeric" placeholder="예: 30000"><p class="tiny muted mt-2">상담 참고용 예산입니다. 확정 판매가나 결제 금액으로 합산하지 않습니다.</p></div><div class="cc-step"><label for="reception-note">추가 요청 <small>선택</small></label><textarea class="textarea" id="reception-note" name="reception_note" maxlength="500" placeholder="예: 식사가 필요해요, 알레르기, 희망 세팅 위치"></textarea></div></form><div class="cc-result card" data-reception-result aria-live="polite"><div class="cc-total"><span>선택한 구성</span><b>상담 후 견적</b></div><p>원하는 방식과 인원을 선택해 주세요. 미확정 금액은 합계에 포함하지 않습니다.</p><a class="btn btn-primary cc-go" href="/inquiry/?reception=cf-custom#reserve">케이터링 상담하기 →</a></div></div></div></section>'''
 main+='<section class="section sec-line" id="catalog"><div class="container">'+head('Explore the menu','우리 행사에 담고 싶은 메뉴','메뉴를 하나씩 고르지 않아도 됩니다. 참고 메뉴를 둘러보거나, 원하는 메뉴만 선택적으로 희망 목록에 담아 주세요.')+'<p class="reception-note mb-3">'+e(DATA['menuNote'])+' 개별 메뉴와 음료 가격도 부가세 별도이며, 최종 견적에서 출장·세팅비와 함께 확인합니다.</p><div class="cf-filters" role="group" aria-label="메뉴 분류"><button type="button" data-menu-filter="all" aria-pressed="true">전체</button>'+''.join(f'<button type="button" data-menu-filter="{c["id"]}" aria-pressed="false">{e(c["name"])}</button>' for c in DATA['categories'])+'</div><p class="small" data-menu-count aria-live="polite">대표 메뉴 30종</p><div class="reception-catalog cf-catalog">'
 for item in DATA['items']:
  main+=f'<article class="reception-item" data-menu-card="{item["id"]}" data-category="{item["category"]}">{photo(item["image"].split("/")[-1],item["name"]+" 메뉴 참고 사진")}<div><h3>{e(item["name"])}</h3><p>제공량·가격 상담</p><button class="btn btn-light btn-sm" type="button" data-menu-pick="{item["id"]}" aria-pressed="false">희망 메뉴에 담기</button></div></article>'
 main+='</div><div class="cf-catalog-actions"><button class="btn btn-light" type="button" data-menu-more>메뉴 더 보기</button><a class="btn btn-primary" href="#calc">선택한 메뉴로 상담하기 ↑</a></div><p class="tiny muted mt-3">사진: 카페프렌즈 제공 메뉴 참고 이미지. 사진 속 식기·장식·음료는 기본 포함 항목을 뜻하지 않습니다.</p></div></section>'
 main+='<section class="section sec-white sec-line" id="gallery"><div class="container">'+head('Catering in real spaces','공간과 행사가 달라지면, 세팅도 달라집니다','협력사가 진행한 현장 사례입니다. 메가스팟에서의 세팅은 공간·메뉴·예산에 맞춰 상담합니다.')+'<div class="cf-gallery">'
 for filename,label in [('field-80.jpg','꽃과 기물을 활용한 테이블 연출'),('field-65.jpg','긴 테이블에 준비한 핑거푸드'),('field-76.jpg','공간 분위기에 맞춘 케이터링'),('field-75.jpg','박스형 메뉴와 다과 진열'),('field-78.jpg','개별 다과와 샌드위치 구성')]:
  main+=f'<figure><a href="{IMG+filename}" data-field-photo data-title="{label}">{photo(filename,label+" 협력사 현장 사례")}</a><figcaption>{label}</figcaption></figure>'
 main+='</div></div></section>'
 main+='<section class="section sec-line" id="process"><div class="container">'+head('How it works','문의부터 행사 준비까지')+'<ol class="steps">'+''.join(f'<li class="step"><div class="n">{i}</div><h4>{a}</h4><p>{b}</p></li>' for i,(a,b) in enumerate([('일정·구성 문의','날짜·장소·시간·인원과 희망 방식을 알려 주세요.'),('메뉴·제공량 상담','희망 메뉴·알레르기·예산과 포장을 함께 확인합니다.'),('최종 견적','메뉴 금액·출장·세팅비·부가세와 포함 범위를 안내합니다.'),('주문 확정','최종 수량·준비 일정·변경·취소 조건을 확인합니다.'),('행사 준비','협의한 시간에 준비하며 세팅·철수 시간을 함께 반영합니다.')],1))+'</ol></div></section>'
 faq=[('얼마부터 주문할 수 있나요?','최소 주문 인원·수량과 준비 기간은 메뉴와 제공 방식, 행사 일정에 따라 상담 후 안내합니다. 정해진 가격이 없는 구성은 상담 후 견적이며 무료가 아닙니다.'),('사진 속 메뉴와 세팅이 그대로 제공되나요?','사진은 협력사의 메뉴·진행 사례입니다. 실제 메뉴·제공량·포장·꽃·식기·기물·현장 인력과 세팅·철수 범위는 최종 견적에서 확인합니다.'),('메뉴를 바꿀 수 있나요?',DATA['menuNote']+' 알레르기와 식이 제한은 상담 때 미리 알려 주세요.'),('부가세와 출장·세팅비는 어떻게 계산하나요?','코스 1인 판매가 × 인원에 아래 제공 방식별 출장세팅비 또는 배송비를 더한 뒤 부가세 10%를 추가합니다. 테이블 세팅은 30명 이하부터 구간별 적용하며 50명 단위로 증가합니다. 박스·다과·도시락은 인원수와 관계없이 배송 1건 비용을 적용합니다. 공간 대관료는 별도입니다.'),('배송·세팅·수거가 모두 포함되나요?','제공 방식과 장소에 따라 다릅니다. 배송 방식·주차·반입 동선·배치·기물 대여·현장 운영·철수 여부와 비용을 최종 견적에 표시합니다.'),('출장뷔페·칵테일도 함께 문의할 수 있나요?','든든한 식사는 출장뷔페, 현장 제조 음료는 출장 칵테일로 함께 상담할 수 있습니다. 케이터링 음료·주류·집기와 별도 서비스가 중복 주문되지 않도록 최종 구성을 확인합니다.')]
 fee=lambda key,value:'<span data-cf-fee="'+key+'">'+f'{value:,}원'+'</span>'
