 main+='''<section class="section"><div class="container"><div class="reception-cta"><div class="eyebrow">Plan your event</div><h2 class="h-l mt-1">공간과 케이터링을 한 번에 상담하세요</h2><p class="mt-2">행사 일정과 원하는 구성을 알려 주세요. 제공 가능 여부와 최종 금액을 함께 안내합니다.</p><div class="row mt-3"><a class="btn btn-primary" href="#calc">우리 행사 구성하기 ↑</a><a class="btn btn-light" href="tel:01085401886">케이터링 전화 상담</a><a class="btn btn-kakao" href="https://pf.kakao.com/_LnxbmX/chat" target="_blank" rel="noopener">카카오톡 문의</a><a class="btn btn-light" href="/assets/docs/megaspot-reception-guide.pdf?v=VERSION" target="_blank" rel="noopener">소개서 PDF ↗</a></div></div><div class="grid grid-2 reception-services mt-3"><a href="/catering/"><b>든든한 식사가 필요하다면 →</b><span class="small muted">출장뷔페 · 바베큐 · 생맥주</span></a><a href="/cocktail/"><b>현장에서 만드는 한 잔 →</b><span class="small muted">출장 칵테일 · 바텐더 서비스</span></a></div></div></section></main>'''
 html=re.sub(r'<main\b[^>]*>[\s\S]*?</main>',lambda m:main.replace('VERSION',V),html,count=1)
